/**
 * Independent verification of the signed-response possession-proof test vectors
 * generated by scripts/generate-directory-proof-vectors.mjs: the directory set
 * merged as -02 Appendix E.2.3 (IETF issue #120) and the `jwks_uri` set that
 * exercises the same proof on a response that is neither served from the
 * well-known path nor typed as a directory.
 *
 * This script deliberately imports NOTHING from the SDK. It re-derives every
 * value from the published bytes the way a third-party implementer would:
 *
 *   - recomputes Content-Digest from the response body
 *   - rebuilds the signature base from the covered component list parsed out of
 *     Signature-Input, in the order that list gives, rather than from any shared
 *     base-construction helper
 *   - recomputes the JWK thumbprint and uses it to select the key
 *   - verifies with node:crypto against the public key taken from the body
 *
 * Signing and verifying through the same helper only proves self-consistency.
 * This is the second path.
 *
 * Published negatives are checked too, and checked for the stated reason: a
 * negative must fail with exactly one input moved away from the positive, so
 * "it does not verify" cannot be satisfied by an unrelated mistake.
 *
 * Usage:
 *   node scripts/verify-directory-proof-vectors.mjs --all
 *   node scripts/generate-directory-proof-vectors.mjs --set all --json \
 *     | node scripts/verify-directory-proof-vectors.mjs
 *   node scripts/verify-directory-proof-vectors.mjs --from-draft <draft.txt|draft.md>
 *   node scripts/verify-directory-proof-vectors.mjs --from-draft <draft.txt> \
 *     --section "Signed jwks_uri response"
 */
import { createHash, createPublicKey, verify as nodeVerify } from 'node:crypto';
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const EXPECTED_TAG = 'http-message-signatures-directory';

/**
 * Every section name this script knows how to lift out of a draft. Matched case
 * insensitively: the kramdown source titles these sections in title case and
 * the rendered output lowercases them.
 */
const SECTION_NAMES = ['Signed directory response', 'Signed jwks_uri response'];
const hasSection = (line, name) => line.toLowerCase().includes(name.toLowerCase());

const failures = [];
let prefix = '';
const check = (ok, name, detail) => {
  if (!ok) failures.push(prefix ? `[${prefix}] ${name}` : name);
  console.log(
    `${ok ? 'PASS' : 'FAIL'}  ${name}${!ok && detail ? `\n        ${detail}` : ''}`,
  );
};

/**
 * Undo RFC 8792 '\' line wrapping. A line ending in a backslash continues on the
 * next line, whose leading whitespace is the wrapping indent and is dropped.
 * Written to be indifferent to how far the renderer indents the block.
 */
function unfold(lines) {
  const out = [];
  for (const line of lines) {
    if (out.length && out[out.length - 1].endsWith('\\')) {
      out[out.length - 1] = out[out.length - 1].slice(0, -1) + line.trimStart();
    } else {
      out.push(line);
    }
  }
  return out;
}

/**
 * True for a line that starts a new section, in either the kramdown source or
 * the rendered text. The section must be bounded: with two vector sections in
 * one appendix, an unbounded slice would collect both sets of fields and the
 * "printed more than one way" guard below would fire on the second signature.
 */
function isSectionBreak(line) {
  return (
    /^#{1,6}\s/.test(line) ||
    /^Appendix\s/.test(line) ||
    /^[A-Z0-9][A-Z0-9.]*\.\s+[A-Z]/.test(line)
  );
}

/** Pull one vector out of a rendered draft (or the markdown source). */
function fromDraft(path, section) {
  const raw = readFileSync(path, 'utf8').split('\n').map((l) => l.replace(/\r$/, ''));
  // The section name appears more than once: in the .txt table of contents
  // (indented, so not a section break) and in the changelog (a list item). Take
  // the last line that both names the section and starts one, so neither can be
  // mistaken for the vectors themselves.
  const headings = raw
    .map((l, i) => (hasSection(l, section) && isSectionBreak(l) ? i : -1))
    .filter((i) => i >= 0);
  const start = headings.length
    ? headings[headings.length - 1]
    : raw.reduce((acc, l, i) => (hasSection(l, section) ? i : acc), -1);
  if (start < 0) throw new Error(`section "${section}" not found`);
  let end = raw.length;
  for (let i = start + 1; i < raw.length; i++) {
    const otherSection = SECTION_NAMES.some(
      (n) => n.toLowerCase() !== section.toLowerCase() && hasSection(raw[i], n),
    );
    if (isSectionBreak(raw[i]) || otherSection) {
      end = i;
      break;
    }
  }
  const lines = unfold(raw.slice(start, end)).map((l) => l.trim());

  // A field may legitimately be printed more than once (Content-Digest appears
  // both on its own and among the response fields). Every printed copy must be
  // byte-identical: two copies that disagree is exactly the hand-editing error
  // this pass exists to catch.
  const one = (re, what) => {
    const hits = [...new Set(lines.filter((l) => re.test(l)))];
    if (hits.length === 0) throw new Error(`no ${what} found in the section`);
    if (hits.length > 1) {
      throw new Error(`${what} printed ${hits.length} different ways:\n${hits.join('\n')}`);
    }
    return hits[0];
  };

  const authorityLine = one(/^"@authority";req:/, '"@authority";req base line');
  const digestLine = one(/^Content-Digest:/, 'Content-Digest field');
  const inputLine = one(/^Signature-Input:/, 'Signature-Input field');
  const signatureLine = one(/^Signature:/, 'Signature field');
  const bodyLine = one(/^\{"keys":\[/, 'response body');
  const baseParamsLine = one(/^"@signature-params":/, '"@signature-params" base line');

  return {
    id: section,
    authority: authorityLine.replace(/^"@authority";req:\s*/, ''),
    body: bodyLine,
    contentDigest: digestLine.replace(/^Content-Digest:\s*/, ''),
    signatureInput: inputLine.replace(/^Signature-Input:\s*/, ''),
    signature: signatureLine.replace(/^Signature:\s*/, ''),
    publishedBase: [
      authorityLine,
      one(/^"content-digest":/, '"content-digest" base line'),
      baseParamsLine,
    ].join('\n'),
  };
}

const digestOf = (bytes) =>
  `sha-256=:${createHash('sha256').update(bytes, 'utf8').digest('base64')}:`;

/** Rebuild a signature base from a covered component list, in list order. */
function rebuildBase(componentList, sigParamsValue, authority, contentDigest) {
  const components = componentList.match(/"[^"]*"(?:;[a-z]+)*/g) ?? [];
  const baseLines = components.map((component) => {
    if (component === '"@authority";req') return `"@authority";req: ${authority}`;
    if (component === '"content-digest"') return `"content-digest": ${contentDigest}`;
    throw new Error(`unexpected covered component: ${component}`);
  });
  baseLines.push(`"@signature-params": ${sigParamsValue}`);
  return { base: baseLines.join('\n'), components };
}

function verifyVector(source, now) {
  const authority = source.authority ?? source.request?.authority;
  const { body, contentDigest, signatureInput, signature } = source;

  console.log(`authority: ${authority}`);
  console.log(`body:      ${body}\n`);

  // 1. Content-Digest, recomputed from the body bytes.
  const ourDigest = digestOf(body);
  check(
    ourDigest === contentDigest,
    'Content-Digest recomputed from the body matches the published value',
    ourDigest === contentDigest ? '' : `computed ${ourDigest}, published ${contentDigest}`,
  );

  // 2. Parse the Signature-Input dictionary member. Everything after "label=" is
  //    the signature params serialization that the base's last line must carry.
  const inputMatch = /^([A-Za-z0-9_-]+)=(\(([^)]*)\)(.*))$/.exec(signatureInput);
  if (!inputMatch) throw new Error(`unparseable Signature-Input: ${signatureInput}`);
  const [, label, sigParamsValue, componentList, paramTail] = inputMatch;

  const params = {};
  for (const m of paramTail.matchAll(/;([a-z]+)=("([^"]*)"|[0-9]+)/g)) {
    params[m[1]] = m[3] !== undefined ? m[3] : Number(m[2]);
  }
  check(params.tag === EXPECTED_TAG, `tag is "${EXPECTED_TAG}"`, `got ${JSON.stringify(params.tag)}`);
  check(typeof params.created === 'number', 'created is present');
  check(typeof params.expires === 'number', 'expires is present');
  check(typeof params.keyid === 'string', 'keyid is present');

  // 3. Rebuild the signature base from the covered component list, in list order.
  const { base, components } = rebuildBase(componentList, sigParamsValue, authority, ourDigest);
  check(
    components.length === 2,
    'exactly the two components the possession proof requires are covered',
    `got ${JSON.stringify(components)}`,
  );

  if (source.publishedBase !== undefined) {
    check(
      base === source.publishedBase,
      'independently rebuilt base is byte-identical to the base printed in the draft',
      base === source.publishedBase ? '' : `rebuilt:\n${base}\npublished:\n${source.publishedBase}`,
    );
  }

  // 4. Select the key by independently recomputed thumbprint.
  const jwks = JSON.parse(body);
  const jwk = jwks.keys.find((k) => {
    const canonical = JSON.stringify({ crv: k.crv, kty: k.kty, x: k.x });
    return createHash('sha256').update(canonical).digest('base64url') === params.keyid;
  });
  check(
    Boolean(jwk),
    'a key in the published body has a thumbprint equal to the signature keyid',
    `keyid ${params.keyid}`,
  );
  if (jwk) {
    check(jwk.kid === params.keyid, 'the published JWK kid equals that thumbprint', `kid ${jwk.kid}`);
  }

  // 5. Verify, with no code in common with the signer.
  const sigMatch = new RegExp(`^${label}=:([^:]*):$`).exec(signature);
  if (!sigMatch) throw new Error(`unparseable Signature for label ${label}: ${signature}`);
  const sigBytes = Buffer.from(sigMatch[1], 'base64');
  check(sigBytes.length === 64, 'signature is a 64 byte Ed25519 signature', `got ${sigBytes.length}`);

  const publicKey = createPublicKey({ key: jwk, format: 'jwk' });
  check(
    nodeVerify(null, Buffer.from(base, 'utf8'), publicKey, sigBytes),
    'Ed25519 signature verifies over the independently rebuilt base',
  );

  // 6. The window a verifier would apply: created must not be in the future,
  //    expires must not have passed.
  check(params.created <= now, 'created is not in the future', `created ${params.created}, now ${now}`);
  check(params.expires > now, 'expires has not passed', `expires ${params.expires}, now ${now}`);

  // 7. Published negatives. Each moves exactly one input away from the positive,
  //    so a failure here is attributable to the reason the vector states.
  for (const negative of source.negatives ?? []) {
    const negDigest = digestOf(negative.body);
    check(
      negDigest === negative.contentDigest,
      `${negative.id}: Content-Digest recomputed from the modified body matches its published value`,
      `computed ${negDigest}, published ${negative.contentDigest}`,
    );
    const digestMoved = negDigest !== ourDigest;
    const authorityMoved = negative.authority !== authority;
    const moved = [digestMoved && 'content-digest', authorityMoved && '@authority'].filter(Boolean);
    const expected = negative.expect === 'content-digest mismatch' ? ['content-digest'] : ['@authority'];
    check(
      moved.length === 1 && moved[0] === expected[0],
      `${negative.id}: exactly the stated input differs from the positive vector (${negative.expect})`,
      `moved ${JSON.stringify(moved)}`,
    );
    const { base: negBase } = rebuildBase(
      componentList,
      sigParamsValue,
      negative.authority,
      negDigest,
    );
    check(
      !nodeVerify(null, Buffer.from(negBase, 'utf8'), publicKey, sigBytes),
      `${negative.id}: the published signature does NOT verify (${negative.expect})`,
    );
  }
}

const argv = process.argv.slice(2);
const flag = (name) => {
  const i = argv.indexOf(name);
  return i >= 0 ? argv[i + 1] : undefined;
};

const nowArg = flag('--now');
const now = nowArg !== undefined ? Number(nowArg) : Math.floor(Date.now() / 1000);

let sources;
let sourceLabel;
const draftPath = flag('--from-draft');
if (draftPath !== undefined) {
  const section = flag('--section') ?? SECTION_NAMES[0];
  sourceLabel = `${draftPath} (${section})`;
  sources = [fromDraft(draftPath, section)];
} else if (argv.includes('--all')) {
  const dir = fileURLToPath(new URL('../vectors/', import.meta.url));
  const files = readdirSync(dir).filter((f) => f.endsWith('.json')).sort();
  if (files.length === 0) throw new Error(`no vector files in ${dir}`);
  sourceLabel = `vectors/ (${files.join(', ')})`;
  sources = files.map((f) => ({
    id: f,
    ...JSON.parse(readFileSync(dir + f, 'utf8')),
  }));
} else {
  const parsed = JSON.parse(readFileSync(0, 'utf8'));
  sourceLabel = 'stdin (generator JSON)';
  sources = Array.isArray(parsed.vectors) ? parsed.vectors : [parsed];
}

console.log(`source:    ${sourceLabel}`);
for (const source of sources) {
  prefix = sources.length > 1 ? String(source.id ?? '') : '';
  console.log(`\n--- ${source.id ?? 'vector'} ---`);
  verifyVector(source, now);
}

console.log(`\n${failures.length === 0 ? 'ALL CHECKS PASSED' : `${failures.length} CHECK(S) FAILED`}`);
for (const failure of failures) console.log(`  ${failure}`);
process.exit(failures.length === 0 ? 0 : 1);
